def _bucket_index(line: bytes, p: int) -> int:
    """Stable bucket for a line: blake2b digest interpreted mod p."""
    digest = hashlib.blake2b(line, digest_size=16).digest()
    return int.from_bytes(digest, "big") % p


def _iter_lines(path):
    """Stream a file line by line (binary, newline-terminated)."""
    with open(path, "rb") as f:
        yield from f


def _partition(lines, base_prefix, p):
    """Stream `lines` into p bucket files. Returns {path: raw_line_count}."""
    names = [f"{base_prefix}.{i:05d}" for i in range(p)]
    handles = [open(n, "wb") for n in names]
    counts = [0] * p
    try:
        for line in lines:
            i = _bucket_index(line, p)
            handles[i].write(line)
            counts[i] += 1
    finally:
        for h in handles:
            h.close()
    return {names[i]: counts[i] for i in range(p) if counts[i]}

